import{_ as t}from"./chunks/Audio.COine8Wh.js";import{c as s,o,j as i,G as a,ae as n,a as r}from"./chunks/framework.Bw0Gm4PQ.js";const u=JSON.parse('{"title":"MODIFYING DUTIES ADDRESSING THE SYNTHETIC OPIOID SUPPLY CHAIN IN THE PEOPLE’S REPUBLIC OF CHINA","description":"","frontmatter":{"legisId":"2025-11-04-modifying-duties-addressing-the-synthetic-opioid-supply-chain-in-the-peoples-republic-of-china","title":"MODIFYING DUTIES ADDRESSING THE SYNTHETIC OPIOID SUPPLY CHAIN IN THE PEOPLE’S REPUBLIC OF CHINA","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/11/modifying-duties-addressing-the-synthetic-opioid-supply-chain-in-the-peoples-republic-of-china/","publishDate":"2025-11-04T17:29:19-05:00"},"headers":[],"relativePath":"executive-orders/2025-11-04-modifying-duties-addressing-the-synthetic-opioid-supply-chain-in-the-peoples-republic-of-china.md","filePath":"executive-orders/2025-11-04-modifying-duties-addressing-the-synthetic-opioid-supply-chain-in-the-peoples-republic-of-china.md"}'),l={name:"executive-orders/2025-11-04-modifying-duties-addressing-the-synthetic-opioid-supply-chain-in-the-peoples-republic-of-china.md"},f=Object.assign(l,{setup(d){return(p,e)=>(o(),s("div",null,[e[0]||(e[0]=i("h1",{id:"modifying-duties-addressing-the-synthetic-opioid-supply-chain-in-the-people-s-republic-of-china",tabindex:"-1"},[r("MODIFYING DUTIES ADDRESSING THE SYNTHETIC OPIOID SUPPLY CHAIN IN THE PEOPLE’S REPUBLIC OF CHINA "),i("a",{class:"header-anchor",href:"#modifying-duties-addressing-the-synthetic-opioid-supply-chain-in-the-people-s-republic-of-china","aria-label":'Permalink to "MODIFYING DUTIES ADDRESSING THE SYNTHETIC OPIOID SUPPLY CHAIN IN THE PEOPLE’S REPUBLIC OF CHINA"'},"​")],-1)),a(t),e[1]||(e[1]=n('<p>Published on Tuesday, November 4, 2025</p><ul><li><p>The President, using authority from the Constitution and various laws, determines necessary actions against synthetic opioids from China.</p></li><li><p><strong>Executive Order 14195 (February 1, 2025)</strong>:</p><ul><li>Declares a national emergency due to China&#39;s failure to address the flow of synthetic opioids like fentanyl into the U.S.</li><li>Imposes a 10% additional duty on products from China related to this issue.</li></ul></li><li><p><strong>Executive Order 14228 (March 3, 2025)</strong>:</p><ul><li>Increases the additional duty from 10% to 20% due to inadequate Chinese action against the drug crisis.</li></ul></li><li><p>Following discussions, China commits to measures to curb fentanyl export, leading the U.S. to reduce the duty back to 10%, effective November 10, 2025.</p></li><li><p><strong>Adjustment of Duty Rates</strong>:</p><ul><li>All articles that were subject to the 20% duty will now be subject to a 10% duty starting November 10, 2025.</li><li>Modifications to the Harmonized Tariff Schedule will reflect this change.</li></ul></li><li><p>The Secretary of Homeland Security will:</p><ul><li>Monitor China&#39;s compliance with commitments.</li><li>Update the President on the situation and propose further actions if necessary.</li></ul></li><li><p>The Secretary is authorized to implement this order as necessary, with executive departments required to assist.</p></li><li><p>Invalidity of any provision does not affect the remainder of the order.</p></li><li><p>The order doesn&#39;t affect existing authorities or create enforceable rights against the U.S.</p></li><li><p>Costs for publication are to be covered by the Department of Homeland Security.</p></li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/11/modifying-duties-addressing-the-synthetic-opioid-supply-chain-in-the-peoples-republic-of-china/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/11/modifying-duties-addressing-the-synthetic-opioid-supply-chain-in-the-peoples-republic-of-china/</a></p>',3))]))}});export{u as __pageData,f as default};
